use js_runtime::{Runtime,Value};use js_runtime::property_slots::LiteralReadSite;use std::hint::black_box;static READ:LiteralReadSite=LiteralReadSite::new("method");
fn main(){for depth in [1,3]{for mode in ["baseline","bloom","prototype"]{let mut rt=Runtime::new();if mode!="baseline"{rt.enable_trusted_generated_property_caches();rt.set_prototype_property_slots_enabled(mode=="prototype");}let owner=rt.object();let key=rt.intern("method");rt.define_data(owner,key,Value::Number(3.0),true,true,true).unwrap();let mut proto=owner;for _ in 1..depth{let p=rt.object();rt.set_prototype(p,proto).unwrap();proto=p;}let receivers=(0..10).map(|_|{let x=rt.object();rt.set_prototype(x,proto).unwrap();for i in 0..40{let k=rt.intern(&format!("field{i}"));rt.define_data(x,k,Value::Number(i as f64),true,true,true).unwrap();}x}).collect::<Vec<_>>();for _ in 0..1000{black_box(rt.get_literal_cached(receivers[0],&READ).unwrap());}let mut times=Vec::new();for _ in 0..7{let start=std::time::Instant::now();for i in 0..200_000{black_box(rt.get_literal_cached(receivers[i%10],&READ).unwrap());}times.push(start.elapsed().as_nanos());}println!("{mode}\t{depth}\t{:?}",times);}}}
